#!/bin/bash
# ljos memory pack for Snellius, generated from the snelnext handbook ingest. Run once per seat.
set -u
ljos persona snellius --anchor 0.3 --about snellius,slurm,login,scratch,sbatch,eessi,hpc,partition --view 'Snellius'"'"'s advisor on the batch system. Judges every command by where it runs and what it costs other users, and stops at the first one that belongs in a job.'
ljos persona hpcsite --anchor 0.4 --about hpc,slurm,batch,login,scratch,quota --view 'Operates a shared HPC site, any of them. Reads an agent'"'"'s plan for load on shared nodes, for secrets in prompts or scripts, and for work that bypasses the scheduler.'
ljos prefer 'On Snellius a login node is for preparing, submitting, checking and copying. Builds, downloads, checksum injection, clones and tests go into a batch job.'
ljos prefer 'Interactive work on Snellius happens inside an salloc on a compute node, never on the login node. Take the allocation first, then run everything else there.'
ljos prefer 'Never poll squeue or sacct in a loop on Snellius. Submit, then read the result once when the job'"'"'s output file exists.'
ljos prefer 'Every Snellius job script states partition, walltime, nodes, tasks, cpus and output path. A script with no walltime gets ten minutes.'
ljos prefer 'No secret, key or token goes into a prompt, a script, a repository or a log. Tokens for an HPC site stay in the person'"'"'s own store.'
ljos prefer 'One job per task on Snellius is a burst. Many small tasks run inside one allocation with HyperQueue, QCG-PilotJob or Snakemake driving them.'
ljos prefer 'Never walk a filesystem or run a bare squeue, sacct -a, who or ps aux on Snellius; they show other people'"'"'s data. Point at one directory and one job.'
ljos remember 'Five failed logins ban a Snellius login node for a day. An agent that retries a connection does that to the person.'
ljos remember 'On Snellius /tmp and /var/tmp are off limits; use $TMPDIR. Large copies and deletes run with mpifileutils in one batch job, never rm -rf or cp on a login node.'
ljos remember 'The Snellius staging partition is the place for transfers and downloads; cbuild with --fakeroot builds container images. Neither runs on a login node.'
ljos remember 'Apptainer on Snellius binds home by default; a jailed agent uses --containall and binds one directory, started on a compute node. bwrap is installed for the same purpose.'
ljos remember 'On Snellius a trial is one job of at most one hour on thin, fat or gpu, not a cancel-and-resubmit loop. The interactive GPU node kills host jobs after 15 minutes.'
ljos remember 'Snellius rome: 521 nodes of 128 cores and 224 GiB. Smallest allocation 1/8 node: 16 cores + 28 GiB RAM; 1.0 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius genoa: 737 nodes of 192 cores and 336 GiB. Smallest allocation 1/8 node: 24 cores + 42 GiB RAM; 1.0 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius fat_rome: 72 nodes of 128 cores and 960 GiB. Smallest allocation 1/8 node: 16 cores + 120 GiB RAM; 1.5 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius fat_genoa: 48 nodes of 192 cores and 1440 GiB. Smallest allocation 1/8 node: 24 cores + 180 GiB RAM; 1.5 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius himem_4tb: 2 nodes of 128 cores and 3840 GiB. Smallest allocation 1/8 node: 16 cores + 480 GiB RAM; 2.0 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius himem_8tb: 2 nodes of 128 cores and 7680 GiB. Smallest allocation 1/8 node: 16 cores + 960 GiB RAM; 3.0 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius gpu_a100: 63 nodes of 72 cores and 480 GiB, 4 GPUs. Smallest allocation 1/4 node: 18 cores + 1 GPU + 120 GiB RAM; 128.0 SBU per GPU-hour; 120 h walltime.'
ljos remember 'Snellius gpu_h100: 88 nodes of 64 cores and 720 GiB, 4 GPUs. Smallest allocation 1/4 node: 16 cores + 1 GPU + 180 GiB RAM (host); 192.0 SBU per GPU-hour; 120 h walltime.'
ljos remember 'Snellius gpu_mig: 4 nodes of 72 cores and 480 GiB, 8 GPUs. Smallest allocation 1/8 node: 9 cores + 1 GPU (MIG) + 60 GiB RAM; 64.0 SBU per GPU-hour; 120 h walltime.'
ljos remember 'Snellius gpu_vis: 63 nodes of 72 cores and 480 GiB, 4 GPUs. Smallest allocation 1/4 node: 18 cores + 1 GPU + 120 GiB RAM; 128.0 SBU per GPU-hour; 24 h walltime.'
ljos remember 'Snellius staging: 10 nodes of 16 cores and 224 GiB. Smallest allocation 1 thread + 7 GiB RAM; 2.0 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius cbuild: 10 nodes of 16 cores and 224 GiB. Smallest allocation 1 thread + 7 GiB RAM; 2.0 SBU per core-hour; 120 h walltime.'
ljos remember 'Snellius home is 200 GiB and one million files, backed up nightly, kept 15 weeks after the project. It is the wrong place for a build tree or a parallel run.'
ljos remember 'Snellius scratch-local and scratch-shared share 8 TiB and a soft limit of 3 million files. Files older than 6 and 14 days are removed, and nothing there is backed up.'
ljos remember 'Snellius scratch-node lives only on fcn nodes and some tcn and gcn nodes, with no quota, and is deleted when the job ends. Request it with --constraint=scratch-node.'
ljos remember 'Snellius project space under /projects lasts the project and has no backup; the archive under /archive is mounted on login and staging nodes only.'
ljos remember 'On Snellius an SBU estimate comes from sbucalc, one row per workflow step with node type, nodes, walltime and repeats. A single headline number is not an estimate.'
